-- ========================================================


function VirtualTargetsController:__init()

    self.humanFollow = nil
    self.catFollow = nil    

    self.isInit = false
    self.controller = nil
end


function VirtualTargetsController:__delete()
end




function VirtualTargetsController:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================

    -----
    self.SetVirtualTargetToCat = function()
        self._currentFollow = self.catFollow
    end
    self.SetVirtualTargetToHuman = function()
        self._currentFollow = self.humanFollow
    end
    EventsModule.AddListener(GameContants.SwitchVirtualTargetToCat,     self.SetVirtualTargetToCat )
    EventsModule.AddListener(GameContants.SwitchVirtualTargetToHuman,   self.SetVirtualTargetToHuman )
end


function VirtualTargetsController:OnDestroy()

    EventsModule.RemoveListener(GameContants.SwitchVirtualTargetToCat,     self.SetVirtualTargetToCat )
    EventsModule.RemoveListener(GameContants.SwitchVirtualTargetToHuman,   self.SetVirtualTargetToHuman )
    self.SetVirtualTargetToCat = nil 
    self.SetVirtualTargetToHuman = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function VirtualTargetsController:Init( humanFollow_, catFollow_, initIndex_ )

    self.humanFollow = humanFollow_
    self.catFollow = catFollow_

    if initIndex_ == RoleMorphologyType.Human then 
        self._currentFollow = self.humanFollow
    elseif initIndex_ == RoleMorphologyType.Cat then
        self._currentFollow = self.catFollow
    else    
        printError("koko- 参数 initIndex_ 异常: " .. tostring(initIndex_) )
    end
    ---
    self.isInit = true
end


-- =========================================== Self ================================================ --


function VirtualTargetsController:GetCurrentFollow()
    return self._currentFollow
end




return VirtualTargetsController
